        f = p.get("finding") or {}
        return f"Link {p['field'].replace('finding:', 'F')} as {p['proposed_value']}" + (f": {f['title']}" if f.get("title") else "")
    if k == "new_requirement":
        return p["reason"] or "New requirement drafted by the AI"
